1	//! Aarch64 addressing mode.
2	
3	use super::regs;
4	use crate::Result;
5	use crate::{
6	    masm::{IntScratch, MacroAssembler as Masm, OperandSize, RegImm},
7	    reg::Reg,
8	};
9	use cranelift_codegen::ir::{Type, types};
10	use cranelift_codegen::isa::aarch64::inst::{
11	    AMode, ExtendOp, PairAMode, SImm7Scaled, SImm9, UImm12Scaled,
12	};
13	
14	/// Aarch64 indexing mode.
15	#[derive(Copy, Clone, Debug, Eq, PartialEq)]
16	pub(crate) enum Indexing {
17	    /// Pre-indexed.
18	    Pre,
19	    /// Post-indexed.
20	    Post,
21	}
22	
23	/// Memory address representation.
24	#[derive(Debug, Copy, Clone)]
25	pub(crate) enum Address {
26	    /// Base register with an arbitrary offset.
27	    Offset {
28	        /// Base register.
29	        base: Reg,
30	        /// Offset.
31	        offset: i64,
32	    },
33	    /// SP-indexed addressing mode for single register loads/stores.
34	    SPIndexedSingle {
35	        /// 9-bit signed offset.
36	        offset: SImm9,
37	        /// Indexing mode (pre or post).
38	        indexing: Indexing,
39	    },
40	    /// SP-indexed addressing mode for register pair loads/stores.
41	    SPIndexedPair {
42	        /// 7-bit signed scaled offset.
43	        offset: SImm7Scaled,
44	        /// Indexing mode (pre or post).
45	        indexing: Indexing,
46	    },
47	}
48	
49	impl Address {
50	    /// Create a pre-indexed addressing mode from the stack pointer for single register operations.
51	    pub fn pre_indexed_from_sp(offset: SImm9) -> Self {
52	        Self::SPIndexedSingle {
53	            offset,
54	            indexing: Indexing::Pre,
55	        }
56	    }
57	
58	    /// Create a post-indexed addressing mode from the stack pointer for single register operations.
59	    pub fn post_indexed_from_sp(offset: SImm9) -> Self {
60	        Self::SPIndexedSingle {
61	            offset,
62	            indexing: Indexing::Post,
63	        }
64	    }
65	
66	    /// Create a pre-indexed addressing mode from the stack pointer for register pair operations.
67	    pub fn pre_indexed_from_sp_for_pair(offset: SImm7Scaled) -> Self {
68	        Self::SPIndexedPair {
69	            offset,
70	            indexing: Indexing::Pre,
71	        }
72	    }
73	
74	    /// Create a post-indexed addressing mode from the stack pointer for register pair operations.
75	    pub fn post_indexed_from_sp_for_pair(offset: SImm7Scaled) -> Self {
76	        Self::SPIndexedPair {
77	            offset,
78	            indexing: Indexing::Post,
79	        }
80	    }
81	
82	    /// Create an offset addressing mode with the shadow stack pointer register as a base.
83	    pub fn from_shadow_sp(offset: i64) -> Self {
84	        Self::Offset {
85	            base: regs::shadow_sp(),
86	            offset,
87	        }
88	    }
89	
90	    /// Create register and arbitrary offset addressing mode.
91	    pub fn offset(base: Reg, offset: i64) -> Self {
92	        // This exists to enforce the sp vs shadow_sp invariant, the
93	        // sp generally should not be used as a base register in an
94	        // address. In the cases where its usage is required and where
95	        // we are sure that it's 16-byte aligned, the address should
96	        // be constructed via the SP-indexed constructors.
97	        // For more details around the stack pointer and shadow stack
98	        // pointer see the docs at regs::shadow_sp().
99	        assert!(
100	            base != regs::sp(),
101	            "stack pointer not allowed in arbitrary offset addressing mode"
102	        );
103	        Self::Offset { base, offset }
104	    }
105	
106	    /// Converts self to cranelift's [`PairAMode`].
107	    /// # Panics
108	    /// This function panics if self cannot be converted to [`PairAMode`].
109	    /// NB: that all uses of this function currently guarantee that
110	    /// the offset will fit in a 7-bit signed offset.
111	    pub fn to_pair_addressing_mode(self) -> PairAMode {
112	        match self {
113	            Self::SPIndexedPair { offset, indexing } => {
114	                if indexing == Indexing::Pre {
115	                    PairAMode::SPPreIndexed { simm7: offset }
116	                } else {
117	                    PairAMode::SPPostIndexed { simm7: offset }
118	                }
119	            }
120	            _ => panic!("Could not convert addressing mode to PairAMode"),
121	        }
122	    }
123	
124	    /// Converts self to cranelift's [`AMode`].
125	    /// The closure parameter ensures that the caller scope is kept in
126	    /// sync with the scratch register used for materializing the
127	    /// general register and offset addressing mode.
128	    /// # Panics
129	    /// This function panics if self cannot be converted to [`AMode`].
130	    pub fn to_addressing_mode<M: Masm>(
131	        self,
132	        masm: &mut M,
133	        size: OperandSize,
134	        f: impl FnOnce(&mut M, AMode) -> Result<()>,
135	    ) -> Result<()> {
136	        use Address::*;
137	        use Indexing::*;
138	
139	        match self {
140	            SPIndexedSingle { offset, indexing } => {
141	                let amode = if indexing == Pre {
142	                    AMode::SPPreIndexed { simm9: offset }
143	                } else {
144	                    AMode::SPPostIndexed { simm9: offset }
145	                };
146	
147	                f(masm, amode)
148	            }
149	            Offset { base, offset } => {
150	                if let Some(simm9) = SImm9::maybe_from_i64(offset) {
151	                    f(
152	                        masm,
153	                        AMode::Unscaled {
154	                            rn: base.into(),
155	                            simm9,
156	                        },
157	                    )
158	                } else if let Some(uimm12) =
159	                    UImm12Scaled::maybe_from_i64(offset, map_to_scale_type(size))
160	                {
161	                    f(
162	                        masm,
163	                        AMode::UnsignedOffset {
164	                            rn: base.into(),
165	                            uimm12,
166	                        },
167	                    )
168	                } else {
169	                    masm.with_scratch::<IntScratch, _>(|masm, temp| {
170	                        masm.mov(temp.writable(), RegImm::i64(offset), OperandSize::S64)?;
171	                        f(
172	                            masm,
173	                            AMode::RegExtended {
174	                                rn: base.into(),
175	                                rm: temp.inner().into(),
176	                                extendop: ExtendOp::SXTX,
177	                            },
178	                        )
179	                    })
180	                }
181	            }
182	            _ => panic!("Could not convert addressing mode to AMode"),
183	        }
184	    }
185	
186	    /// Returns the register base and immediate offset of the given [`Address`].
187	    ///
188	    /// # Panics
189	    /// This function panics if the [`Address`] is not [`Address::Offset`].
190	    pub fn unwrap_offset(&self) -> (Reg, i64) {
191	        match self {
192	            Self::Offset { base, offset } => (*base, *offset),
193	            _ => panic!("Expected register and offset addressing mode"),
194	        }
195	    }
196	}
197	
198	fn map_to_scale_type(size: OperandSize) -> Type {
199	    match size {
200	        OperandSize::S8 => types::I8,
201	        OperandSize::S16 => types::I16,
202	        OperandSize::S32 => types::I32,
203	        OperandSize::S64 => types::I64,
204	        OperandSize::S128 => types::I8X16,
205	    }
206	}
